{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "In healthy subjects, 5-hydroxyrofecoxib had an absolute oral bioavailability of 14.9% after a 10 mg oral dose, below the 20% threshold; this high-transfer lactone-containing analogue supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "EM574, a polyoxygenated macrolide lactone, showed an estimated human oral bioavailability of about 2%, strongly supporting low F for the similarly lactone-rich query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "9-Nitrocamptothecin, a lactone-containing drug, exhibited very low absolute oral bioavailability in patients, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hydroxysafflor yellow A, a highly polar polyhydroxylated natural product, had low oral bioavailability in healthy volunteers, consistent with the query's high polarity and low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Baicalin, a polar glycoside, showed poor oral bioavailability in healthy subjects, supporting low F for the query's highly oxygenated scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A macrocyclic lactone glycoside analogue showed potentially low absolute bioavailability in a healthy adult, providing high-transfer supportive evidence for low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Artemisinin showed an absolute oral bioavailability of 61% in Thai patients in one study, but this is contradicted by multiple other artemisinin reports of low/poor bioavailability and has only moderate transfer; it does not outweigh the high-transfer low-F analogues.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ixabepilone had an absolute oral bioavailability of 41.3% in patients, above the threshold, but its low transfer and structural differences (thiazole/amide macrocycle) limit applicability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of high-transfer experimental evidence from lactone/polyoxygenated analogues (5-hydroxyrofecoxib ~14-15%, EM574 ~2%, 9-NC very low, HSYA low, baicalin poor) indicates that the query's multiple lactones and high polarity will limit oral absorption, making F≥20% unlikely. Lower-transfer high-F analogues (ixabepilone, zidovudine, and some artemisinin studies) are structurally less relevant and do not overcome this pattern.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "Artemisinin evidence is conflicting, with some absolute F values above 20%.",
    "Transfer scores reflect assay context rather than exact structural similarity; no exact analogue of the query's cage-like polyol lactone system was tested."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

